status
UA_encodeBinaryInternal(const void *src, const UA_DataType *type,
                        u8 **bufPos, const u8 **bufEnd,
                        UA_EncodeBinaryOptions *options,
                        UA_exchangeEncodeBuffer exchangeCallback,
                        void *exchangeHandle) {
    if(!type || !src)
        return UA_STATUSCODE_BADENCODINGERROR;

    /* Set up the context */
    Ctx ctx;
    memset(&ctx, 0, sizeof(Ctx));
    ctx.pos = *bufPos;
    ctx.end = *bufEnd;
    ctx.depth = 0;
    ctx.exchangeBufferCallback = exchangeCallback;
    ctx.exchangeBufferCallbackHandle = exchangeHandle;
    if(options)
        ctx.opts.namespaceMapping = options->namespaceMapping;

    /* Encode */
    status ret = encodeWithExchangeBuffer(&ctx, src, type);
    UA_assert(ret != UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED);

    /* Set the new buffer position for the output. Beware that the buffer might
     * have been exchanged internally. */
    *bufPos = ctx.pos;
    *bufEnd = ctx.end;
    return ret;
}

/* Encode without a buffer to compute the size. The size is only set for a
 * good status. */
static status
calcSizeBinaryInternal(const void *p, const UA_DataType *type,
                       UA_EncodeBinaryOptions *options, size_t *size) {
    /* A non-null sentinel keeps sizing pointer arithmetic well-defined. */
    u8 *pos = (u8*)(uintptr_t)1u;
    const u8 *posEnd = NULL;
    status res = UA_encodeBinaryInternal(p, type, &pos, &posEnd, options, NULL, NULL);
    if(res == UA_STATUSCODE_GOOD)
        *size = (size_t)((uintptr_t)pos - 1u);
    return res;
}

UA_StatusCode
UA_encodeBinary(const void *p, const UA_DataType *type,
                UA_ByteString *outBuf, UA_EncodeBinaryOptions *options) {
    /* Allocate buffer */
    UA_Boolean allocated = false;
    status res = UA_STATUSCODE_GOOD;
    if(outBuf->length == 0) {
        /* Report why the size cannot be computed. Encoding into an empty
         * buffer would only answer BadEncodingError. */
        size_t len = 0;
        res = calcSizeBinaryInternal(p, type, options, &len);
        if(res != UA_STATUSCODE_GOOD)
            return res;
        res = UA_ByteString_allocBuffer(outBuf, len);
        if(res != UA_STATUSCODE_GOOD)
            return res;
        allocated = true;
    }

    /* Encode */
    u8 *pos = outBuf->data;
    const u8 *posEnd = &outBuf->data[outBuf->length];
    res = UA_encodeBinaryInternal(p, type, &pos, &posEnd, options, NULL, NULL);

    /* Clean up */
    if(res == UA_STATUSCODE_GOOD) {
        outBuf->length = (size_t)((uintptr_t)pos - (uintptr_t)outBuf->data);
    } else if(allocated) {
        UA_ByteString_clear(outBuf);
    }
    return res;
}

