yxml_ret_t yxml_eof(yxml_t *x) {
	if(x->state != YXMLS_misc3 &&
	   !(x->contentmode && x->state == YXMLS_misc2 && x->stacklen == 0))
		return YXML_EEOF;
	return YXML_OK;
}

