    UA_FD epollfd;
#endif
    /* Flat array of all fds registered in the EventLoop. Used by the select
     * and GLib backends (epoll keeps the rfd pointer directly in
     * epoll_event.data.ptr instead and does not need this list). */
    UA_RegisteredFD **fds;
    size_t fdsSize;

