    if(!iv || !ctx) return UA_STATUSCODE_BADINTERNALERROR;
    Channel_Context_EccCurve448 *cc = (Channel_Context_EccCurve448 *)ctx;
    UA_ByteString_clear(&cc->localSymIv);
